int main() {
  int total_clothing = 120;
  int load1_clothing = 48;
  int remaining_clothing = total_clothing - load1_clothing;
  int num_small_loads = 9;
  int clothing_per_small_load = remaining_clothing / num_small_loads;

  std::cout << clothing_per_small_load << std::endl;

  return 0;
}
```
